function clinicalAlert(p){const text=p?.clinical?.allergies?.trim();return text?`<aside class="error clinical-alert"><strong>Αλλεργίες / τεκμηρίωση</strong><p>${esc(text)}</p></aside>`:'';}
const smokingOptions=[['unknown','Δεν έχει καταγραφεί'],['never','Μη καπνιστής'],['current','Καπνιστής'],['former','Πρώην καπνιστής']];
function clinicalValues(){return {smoking:$('clinicalSmoking').value,...Object.fromEntries(Object.keys(CLINICAL_FIELDS).map(k=>[k,$('clinical_'+k).value]))};}
function clinicalEditor(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const c=p.clinical||emptyClinical();return `<section class="card">${patientSelect('clinicalPatient',p.id)}<h2>${esc(p.name)}</h2><p>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p>${clinicalAlert(p)}<div class="row">${button('Επισκέψεις / παρακολούθηση','record',p.id,'secondary')}${button('Εξετάσεις & έγγραφα','openExams',p.id,'secondary')}${button('Νέα επίσκεψη','newVisit',p.id)}</div></section><form id="clinicalForm"><section class="card"><div class="eyebrow">Επίπεδο Β · Ιατρικός φάκελος</div><h2>Ιατρικό ιστορικό</h2>${select('Καπνιστής','clinicalSmoking',smokingOptions,c.smoking)}<div class="split">${['familyHistory','medications','allergies','diagnoses'].map(k=>`<label>${CLINICAL_FIELDS[k]}<textarea id="clinical_${k}">${esc(c[k])}</textarea></label>`).join('')}</div><p class="field-hint">Στα φάρμακα καταχωρίζετε την αγωγή για παρακολούθηση. Η επίσημη συνταγογράφηση γίνεται στην ΗΔΙΚΑ.</p></section><section class="card"><div class="eyebrow">Επίπεδο Γ · Ουρολογία–Ανδρολογία</div><h2>Εξειδικευμένο ιστορικό</h2>${['urologyHistory','andrologyHistory','luts'].map(k=>`<label>${CLINICAL_FIELDS[k]}<textarea id="clinical_${k}" ${k==='luts'?'placeholder="Ελεύθερη καταγραφή δυσκολίας ούρησης, συχνουρίας, νυκτουρίας ή άλλων συμπτωμάτων του φανταστικού περιστατικού."':''}>${esc(c[k])}</textarea></label>`).join('')}<p class="field-hint">Προαιρετικά πεδία με ελεύθερο κείμενο. Δεν απαιτείται άκαμπτο έντυπο.</p><div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση ιατρικού ιστορικού</button></section></form>`;}
function examinationsPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const e=(state.examinations||[]).find(x=>x.id===editingExamination&&x.patientId===p.id);const list=(state.examinations||[]).filter(x=>x.patientId===p.id&&(!examCategory||x.category===examCategory)).sort((a,b)=>b.date.localeCompare(a.date));return `<section class="card">${patientSelect('examPatient',p.id)}<h2>${esc(p.name)}</h2>${clinicalAlert(p)}<div class="row">${button('Ιατρικός φάκελος','openClinical',p.id,'secondary')}${button('Επισκέψεις','record',p.id,'secondary')}${button('Εικόνες / Απεικόνιση','openImaging',p.id,'secondary')}${button('Νέα εξέταση','newExam')}</div>${select('Φίλτρο εξετάσεων','examTypeFilter',[['','Όλες οι εξετάσεις'],...Object.entries(EXAM_TYPES)],examCategory)}</section><section class="card"><h2>${e?'Επεξεργασία':'Καταχώριση'} εξέτασης</h2><form id="examForm"><div class="grid">${select('Κατηγορία εξέτασης','examCategory',Object.entries(EXAM_TYPES),e?.category||examCategory||'ultrasound')}${field('Ημερομηνία · ΗΗ/ΜΜ/ΕΕΕΕ','examDate',e?displayDate(e.date):displayDate(today()),'text','required inputmode="numeric" pattern="[0-9]{2}/[0-9]{2}/[0-9]{4}"')}${field('Τίτλος εξέτασης','examTitle',e?.title||'','text','required maxlength="200"')}</div><div class="split"><label>Αποτελέσματα / τιμή και μονάδα<textarea id="examResult">${esc(e?.result||'')}</textarea></label><label>Τιμές αναφοράς εργαστηρίου<textarea id="examRange">${esc(e?.referenceRange||'')}</textarea></label></div><label>Γνωμάτευση / παρατηρήσεις εξέτασης<textarea id="examNotes">${esc(e?.notes||'')}</textarea></label><label>Συνημμένα αρχεία εξέτασης<input type="file" id="examFiles" multiple accept=".pdf,.png,.jpg,.jpeg,.webp,.dcm,.zip"></label><p class="field-hint">PDF, εικόνες, DICOM ή ZIP σειράς εξέτασης, έως 20 MB ανά αρχείο και 100 MB συνολικά. Η αποθήκευση γίνεται τοπικά στον browser (IndexedDB). Για DICOM/ZIP παρέχεται φύλαξη και λήψη, όχι διαγνωστικός viewer. Μη αποθηκευμένα αρχεία πρέπει να επιλεγούν ξανά μετά από ανανέωση/κλείδωμα.</p>${e?.files.map(f=>`<label><input type="checkbox" data-remove-file="${esc(f.id)}">Αφαίρεση κατά την αποθήκευση: ${esc(f.name)}</label>`).join('')||''}<div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση εξέτασης και αρχείων</button></form></section><section class="card"><h2>Ιστορικό εξετάσεων · ${list.length}</h2>${list.map(x=>`<article class="exam-entry"><div class="row between"><h3>${esc(x.title)}</h3><span class="pill">${displayDate(x.date)} · ${EXAM_TYPES[x.category]}</span></div><p class="prewrap"><strong>Αποτέλεσμα:</strong> ${esc(x.result)||'—'}</p><p class="prewrap"><strong>Τιμές αναφοράς:</strong> ${esc(x.referenceRange)||'—'}</p><p class="prewrap">${esc(x.notes)}</p><ul>${x.files.map(f=>`<li>${esc(f.name)} · ${(f.size/1024).toFixed(1)} KB ${button('Λήψη αρχείου','downloadExam',f.id,'secondary')}${/^image\/(png|jpeg|webp)$/.test(f.type)?button('Προβολή εικόνας','previewExam',f.id,'secondary'):''}</li>`).join('')}</ul><div class="row">${['ultrasound','ct','mri','xray','otherImaging'].includes(x.category)?button('Απεικόνιση / Ευρήματα','openImaging',x.id):''}${button('Επεξεργασία','editExam',x.id,'secondary')}${button('Διαγραφή δοκιμαστικής εξέτασης','removeExam',x.id,'danger')}</div></article>`).join('')||'<p>Δεν έχουν καταχωριστεί εξετάσεις με αυτό το φίλτρο.</p>'}</section>${optionsActions()}`;}
async function blobFingerprint(blob){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer())),b=>b.toString(16).padStart(2,'0')).join('');}
async function saveExamination(){if(!doctor())throw Error('Απαιτείται γιατρός.');const old=(state.examinations||[]).find(e=>e.id===editingExamination);const date=isoDate($('examDate').value);if(!date)throw Error('Συμπληρώστε έγκυρη ημερομηνία εξέτασης.');const selected=[...$('examFiles').files];for(const f of selected)checkFile(f);const removed=new Set([...document.querySelectorAll('[data-remove-file]:checked')].map(e=>e.dataset.removeFile));const retained=(old?.files||[]).filter(f=>!removed.has(f.id));const total=(state.examinations||[]).filter(e=>e.id!==old?.id).flatMap(e=>e.files).reduce((n,f)=>n+f.size,0)+retained.reduce((n,f)=>n+f.size,0)+selected.reduce((n,f)=>n+f.size,0);if(total>100*1024*1024)throw Error('Το σύνολο αρχείων υπερβαίνει τα 100 MB του demo.');const added=[];try{for(const f of selected){const id=uid();await putFile(id,f);added.push({id,name:f.name,type:f.type||'application/octet-stream',size:f.size});}const item={...old,id:old?.id||uid(),patientId:selectedPatient,category:$('examCategory').value,date,title:$('examTitle').value.trim(),result:$('examResult').value,referenceRange:$('examRange').value,notes:$('examNotes').value,files:[...retained,...added]};update(s=>{s.examinations||=[];const i=s.examinations.findIndex(e=>e.id===item.id);if(i<0)s.examinations.push(item);else s.examinations[i]=item;});}catch(err){for(const f of added){try{await deleteFile(f.id);}catch{}}throw err;}for(const id of removed)await deleteFile(id);editingExamination='';render();toast('Η εξέταση και τα αρχεία αποθηκεύτηκαν τοπικά.');}

const imagingTypes=['ultrasound','ct','mri','xray','otherImaging'];
function clearImageURLs(){imageGeneration++;for(const url of imageURLs)URL.revokeObjectURL(url);imageURLs.length=0;}
function imageFiles(exam){return (exam?.files||[]).filter(f=>/^image\/(png|jpeg|webp)$/.test(f.type));}
function imagingPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const all=(state.examinations||[]).filter(e=>e.patientId===p.id&&imagingTypes.includes(e.category)).sort((a,b)=>b.date.localeCompare(a.date));const list=all.filter(e=>!imagingType||e.category===imagingType);let e=list.find(e=>e.id===imagingExam);if(!e){e=list[0];imagingExam=e?.id||'';imagingFile='';}const files=imageFiles(e);if(!files.some(f=>f.id===imagingFile))imagingFile=files[0]?.id||'';if(!all.some(x=>x.id===imagingCompare&&x.id!==imagingExam))imagingCompare='';const compare=all.find(x=>x.id===imagingCompare);return `<section class="card imaging-patient">${patientSelect('imagingPatient',p.id)}<h2>${esc(p.name)}</h2><p>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p>${clinicalAlert(p)}<div class="row">${button('Εξετάσεις / Προσθήκη αρχείων','openExams',p.id,'secondary')}${button('ΤΝ · Μελλοντικός σχεδιασμός','nav','aiDesign','secondary')}</div></section><div class="imaging-layout"><aside class="card imaging-list"><h2>Απεικονίσεις</h2><p class="imaging-state-label">ΕΝΕΡΓΗ ΠΡΟΒΟΛΗ ΑΡΧΕΙΩΝ</p>${select('Κατηγορία','imagingType',[['','Όλες οι απεικονίσεις'],...imagingTypes.map(k=>[k,EXAM_TYPES[k]])],imagingType)}${list.map(x=>`<button type="button" data-action="selectImageExam" data-id="${esc(x.id)}" class="image-exam-choice ${x.id===imagingExam?'selected':''}" aria-pressed="${x.id===imagingExam}"><strong>${esc(x.title)}</strong><span>${displayDate(x.date)} · ${EXAM_TYPES[x.category]}</span><small>${x.files.length} αρχεία</small></button>`).join('')||'<p>Δεν υπάρχουν αποθηκευμένες απεικονίσεις.</p>'}<details><summary>Αρχικό σχέδιο οθόνης</summary><p class="field-hint">Στατική σχεδιαστική αναφορά με υποθετικά στοιχεία· δεν συνδέεται με τον επιλεγμένο φάκελο.</p><a href="imaging-reference.png" target="_blank" rel="noopener">Άνοιγμα σχεδίου σε νέα καρτέλα</a><img class="design-reference" loading="lazy" src="imaging-reference.png" alt="Αρχικό σχεδιαστικό δείγμα οθόνης απεικόνισης"></details></aside><section class="card imaging-center"><h2>${esc(e?.title)||'Προβολή εικόνας'}</h2>${e?`<p>${displayDate(e.date)} · ${EXAM_TYPES[e.category]}</p>`:''}<div class="image-toolbar" role="group" aria-label="Εργαλεία προβολής εικόνας">${button('＋ Μεγέθυνση','imageZoom','in','secondary')}${button('− Σμίκρυνση','imageZoom','out','secondary')}${button('Προσαρμογή','imageZoom','fit','secondary')}${button('Πλήρης οθόνη','imageFull','','secondary')}<output id="imageZoomStatus">100%</output></div>${files.length?select('Αρχείο εικόνας','imageFileSelect',files.map(f=>[f.id,f.name]),imagingFile):''}<div id="primaryViewer" class="image-viewer"><p id="primaryMessage">${e?'Δεν υπάρχει εικόνα PNG/JPEG/WebP σε αυτή την εξέταση. Τα υπόλοιπα αρχεία διατίθενται για λήψη.':'Προσθέστε μια εξέταση και αρχεία από την ενότητα Εξετάσεις.'}</p><img id="primaryImage" hidden alt="Αποθηκευμένο αρχείο της επιλεγμένης απεικόνισης"></div><p class="field-hint">Ενδεικτική προβολή αρχείων εικόνας. Δεν παρέχονται διαγνωστικές μετρήσεις, επεξεργασία DICOM ή αυτόματη ανάλυση.</p>${(e?.files||[]).map(f=>`<p>${esc(f.name)} ${button('Λήψη','downloadExam',f.id,'secondary')}</p>`).join('')}${e?select('Σύγκριση με άλλη εξέταση του ίδιου ασθενή','compareImageExam',[['','Χωρίς σύγκριση'],...all.filter(x=>x.id!==e.id).map(x=>[x.id,displayDate(x.date)+' · '+x.title])],imagingCompare):''}${compare?`<h3>Σύγκριση: ${esc(compare.title)} · ${displayDate(compare.date)}</h3><div class="image-viewer compare-viewer"><p id="compareMessage">Η εξέταση δεν έχει υποστηριζόμενο αρχείο εικόνας.</p><img id="compareImage" hidden alt="Εικόνα άλλης εξέτασης του ίδιου ασθενή για σύγκριση"></div>`:''}</section><section class="card imaging-findings"><h2>Ευρήματα γιατρού</h2>${e?`<form id="imagingForm"><label>Ευρήματα απεικόνισης<textarea id="imageFindings">${esc(e.result)}</textarea></label><label>Συμπέρασμα / εκτίμηση<textarea id="imageConclusion">${esc(e.notes)}</textarea></label><label>Σύγκριση / παρατηρήσεις παρακολούθησης<textarea id="imageComparison">${esc(e.comparisonNote||'')}</textarea></label><p class="field-hint">Ελεύθερη καταχώριση από τον γιατρό, χωρίς προκαθορισμένο όριο χαρακτήρων. Δεν παράγονται ευρήματα ΤΝ.</p><div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση ευρημάτων</button></form>${e.imagingRevisions?.length?`<details><summary>Προηγούμενες καταχωρίσεις · ${e.imagingRevisions.length}</summary>${e.imagingRevisions.map(r=>`<article><small>${esc(r.author)} · ${esc(r.at)}</small><p class="prewrap">${esc(r.result)}</p><p class="prewrap">${esc(r.notes)}</p><p class="prewrap">${esc(r.comparisonNote)}</p></article>`).join('')}</details>`:''}`:'<p>Επιλέξτε ή προσθέστε απεικονιστική εξέταση.</p>'}</section></div>`;}
async function hydrateImaging(){const generation=imageGeneration;const current=(state.examinations||[]).find(e=>e.id===imagingExam&&e.patientId===selectedPatient);const compare=(state.examinations||[]).find(e=>e.id===imagingCompare&&e.patientId===selectedPatient);for(const [exam,fileId,imgId,messageId] of [[current,imagingFile,'primaryImage','primaryMessage'],[compare,imageFiles(compare)[0]?.id,'compareImage','compareMessage']]){if(!fileId||!$(imgId))continue;try{const file=exam?.files.find(f=>f.id===fileId);if(!file)continue;const blob=await getFile(file.id);if(generation!==imageGeneration)return;if(!blob)throw Error('Το αρχείο λείπει από την τοπική αποθήκη. Χρησιμοποιήστε BACKUP για επαναφορά.');const image=$(imgId);if(!image)return;const url=URL.createObjectURL(blob);imageURLs.push(url);image.onload=()=>{if(generation!==imageGeneration)return;image.hidden=false;$(messageId).hidden=true;};image.onerror=()=>{if(generation!==imageGeneration)return;image.hidden=true;$(messageId).hidden=false;$(messageId).textContent='Το αρχείο δεν αναγνωρίζεται ως υποστηριζόμενη εικόνα.';};image.src=url;}catch(err){if(generation===imageGeneration&&$(messageId))$(messageId).textContent=err.message;}}}
function aiDesignPage(){return `<section class="card"><h2>Ανάλυση CT / MRI με ΤΝ · σχεδιαστική πρόταση</h2><div class="notice" role="note"><strong>ΜΕΛΛΟΝΤΙΚΗ ΔΥΝΑΤΟΤΗΤΑ — ΔΕΝ ΕΚΤΕΛΕΙΤΑΙ ΑΝΑΛΥΣΗ.</strong><p>Η παρακάτω εικόνα είναι στατικό mockup με υποθετικά ευρήματα, μετρήσεις και ποσοστά. Δεν αφορά τον επιλεγμένο ασθενή, δεν αποτελεί πραγματική διάγνωση και δεν εισάγεται στον φάκελο.</p></div><p>Η αυτόματη ανίχνευση βλαβών και οι πιθανότητες απαιτούν κατάλληλα επικυρωμένο σύστημα και ξεχωριστή αξιολόγηση πριν ενεργοποιηθούν.</p><div class="row">${button('Σχέδιο CT','aiReference','ct','secondary')}${button('Σχέδιο MRI','aiReference','mri','secondary')}${button('Επιστροφή στην απεικόνιση','nav','imaging','secondary')}<button type="button" disabled>Εκτέλεση ΤΝ · μη διαθέσιμη</button><a href="${aiReference==='mri'?'mri-ai-reference.png':'ct-ai-reference.png'}" target="_blank" rel="noopener">Μεγέθυνση σχεδιαστικής αναφοράς</a></div></section><figure class="card ai-design-reference"><img class="design-reference" src="${aiReference==='mri'?'mri-ai-reference.png':'ct-ai-reference.png'}" alt="Στατικό υποθετικό σχέδιο ανάλυσης CT / MRI με τεχνητή νοημοσύνη, χωρίς ενεργή ανάλυση"><figcaption>Τα στοιχεία και τα ποσοστά της εικόνας είναι αποκλειστικά σχεδιαστικά παραδείγματα.</figcaption></figure>`;}

function dateFilterValue(value){return /[0-9]/.test(value)?isoDate(value)||null:'';}
function assignedClinicSelect(p){return select('Ιατρείο αναφοράς','patientAssignedClinic',[['','Δεν έχει οριστεί'],...clinics().map(c=>[c.id,c.name]),...(p?.assignedClinic==='hospital'&&!state.settings.hospital?[['hospital','Νοσοκομείο · ανενεργό']]:[])],p?.assignedClinic||'');}
function referencePanel(file,label){return `<details class="reference-panel"><summary>${label} · αρχικό σχέδιο</summary><p class="field-hint">Στατική σχεδιαστική αναφορά με υποθετικά στοιχεία. Δεν αποτελεί καταχώριση του επιλεγμένου ασθενή.</p><a href="${file}" target="_blank" rel="noopener">Μεγέθυνση αρχικού σχεδίου</a><img class="design-reference" src="${file}" loading="lazy" alt="${label} · αρχικό σχεδιαστικό δείγμα"></details>`;}
function globalPatientSearch(){return `<div class="global-patient-search"><label for="globalPatientSearch">Αναζήτηση ασθενή</label><input id="globalPatientSearch" type="search" autocomplete="off" placeholder="Όνομα, Α.Μ.Κ.Α., τηλέφωνο…" aria-controls="globalPatientHits"><div id="globalPatientHits" aria-live="polite"></div></div>`;}
function globalPatientHits(q){if(!q.trim())return '';const rows=state.patients.filter(p=>matchesPatient(p,q));return `<div class="global-hits">${rows.slice(0,8).map(p=>button(`${esc(p.name)} · ${p.age} ετών`,doctor()?'patientSummary':'editPatient',p.id,'secondary')).join('')||'<p>Δεν βρέθηκαν ασθενείς.</p>'}${rows.length>8?'<p>Πληκτρολογήστε περισσότερα στοιχεία για πιο συγκεκριμένη αναζήτηση.</p>':''}</div>`;}
function filteredPatients(){return state.patients.filter(p=>matchesPatient(p,patientQuery)&&(!patientStatusFilter||(p.status||'active')===patientStatusFilter)&&(!patientClinicFilter||patientClinics(state,p).includes(patientClinicFilter))&&(!patientFavFilter||!!p.favourite===(patientFavFilter==='yes'))&&(!patientLastFrom||patientLastVisit(state,p.id)?.date>=patientLastFrom)&&(!patientLastTo||patientLastVisit(state,p.id)?.date<=patientLastTo)).sort((a,b)=>(patientSort==='asc'?1:-1)*((a.lastName||a.name).localeCompare(b.lastName||b.name,'el')||(a.firstName||'').localeCompare(b.firstName||'','el')));}
function paginatedPatients(){const rows=filteredPatients();patientPage=Math.max(1,Math.min(patientPage,Math.ceil(rows.length/patientPageSize)||1));return rows.slice((patientPage-1)*patientPageSize,patientPage*patientPageSize);}
function patientsPage(){const open=showPatientForm||!!editingPatient;return `<div class="row between patient-toolbar"><div><h2>Διαχείριση ασθενών</h2><p class="muted">Πραγματικά στοιχεία της τοπικής δοκιμαστικής βάσης.</p></div><div class="row">${button('＋ Νέος ασθενής','newPatient')}${button('Εξαγωγή CSV','exportPatients','','secondary')}</div></div>${open?patientEditor():''}<section class="card patient-table-panel"><div class="patient-filters">${field('Αναζήτηση · όνομα, ηλικία, Α.Μ.Κ.Α., τηλέφωνο','search',patientQuery,'search','autocomplete="off"')}${select('Ιατρείο','patientClinicFilter',[['','Όλα'],...['clinic-1','clinic-2','hospital'].filter(id=>id!=='hospital'||state.settings.hospital||state.patients.some(p=>patientClinics(state,p).includes(id))).map(id=>[id,clinics().find(c=>c.id===id)?.name||(id==='hospital'?'Νοσοκομείο · ιστορικά':'Ιατρείο')])],patientClinicFilter)}${select('Κατάσταση','patientStatusFilter',[['','Όλες'],...Object.entries(PATIENT_STATUSES)],patientStatusFilter)}${select('Αγαπημένοι','patientFavFilter',[['','Όλοι'],['yes','Μόνο αγαπημένοι'],['no','Χωρίς επισήμανση']],patientFavFilter)}</div><details><summary>Περισσότερα φίλτρα · τελευταία επίσκεψη</summary><div class="grid">${field('Από · ΗΗ/ΜΜ/ΕΕΕΕ','patientLastFrom',patientLastFrom?displayDate(patientLastFrom):'','text','inputmode="numeric"')}${field('Έως · ΗΗ/ΜΜ/ΕΕΕΕ','patientLastTo',patientLastTo?displayDate(patientLastTo):'','text','inputmode="numeric"')}</div></details><div class="row between">${button('Καθαρισμός φίλτρων','patientClearFilters','','secondary')}${select('Εγγραφές ανά σελίδα','patientPageSize',[['12','12'],['24','24'],['50','50']],String(patientPageSize))}</div><div id="patientResults">${patientRows()}</div><div id="listFilterError" role="alert"></div></section>${doctor()?optionsActions():''}${referencePanel('patients-reference.png','Πίνακας ασθενών')}`;}
function patientRows(){const all=filteredPatients(),rows=paginatedPatients(),pages=Math.ceil(all.length/patientPageSize)||1;const chips=[['','Όλοι',state.patients.length],...Object.entries(PATIENT_STATUSES).map(([key,label])=>[key,label,state.patients.filter(p=>(p.status||'active')===key).length]),['favourites','Αγαπημένοι',state.patients.filter(p=>p.favourite).length]];const selected=state.patients.filter(p=>selectedPatientIds.has(p.id)).length;return `<div class="patient-chips">${chips.map(([key,label,count])=>button(`${label} · ${count}`,'patientQuickFilter',key,'secondary')).join('')}</div><p class="field-hint">Οι μετρήσεις αφορούν όλες τις καταχωρίσεις. Επιλεγμένοι: ${selected}. Η εξαγωγή αφορά τους επιλεγμένους ή, αν δεν υπάρχουν, όλα τα αποτελέσματα φίλτρων.</p><div class="table-wrap"><table class="patients-table"><thead><tr><th><input type="checkbox" id="selectPatientPage" aria-label="Επιλογή ασθενών αυτής της σελίδας" ${rows.length&&rows.every(p=>selectedPatientIds.has(p.id))?'checked':''}></th><th>★</th><th>${button('Επίθετο '+(patientSort==='asc'?'↑':'↓'),'patientSort','','table-sort')}</th><th>Όνομα</th><th>Ηλικία</th><th>Α.Μ.Κ.Α.</th><th>Φύλο</th><th>Τηλέφωνο</th><th>Τελευταία επίσκεψη</th><th>Κατάσταση</th><th>Ιατρεία</th><th>Ενέργειες</th></tr></thead><tbody>${rows.map(p=>{const visit=patientLastVisit(state,p.id);return `<tr><td><input type="checkbox" data-patient-select="${esc(p.id)}" aria-label="Επιλογή ${esc(p.name)}" ${selectedPatientIds.has(p.id)?'checked':''}></td><td><button type="button" data-action="patientFavourite" data-id="${esc(p.id)}" class="favourite-toggle" aria-label="Αγαπημένος: ${esc(p.name)}" aria-pressed="${!!p.favourite}">${p.favourite?'★':'☆'}</button></td><td>${esc(p.lastName||p.name)}${!p.lastName?'<small class="legacy-name">Ενιαίο παλιό όνομα</small>':''}</td><td>${esc(p.firstName)||'—'}</td><td>${p.age}</td><td class="mono">${esc(p.amka)||'—'}</td><td>${({male:'Άνδρας',female:'Γυναίκα',other:'Άλλο'})[p.sex]||'—'}</td><td>${esc(p.phone)||'—'}</td><td>${visit?displayDate(visit.date):'—'}</td><td><span class="patient-status status-${p.status||'active'}">${PATIENT_STATUSES[p.status||'active']}</span></td><td>${patientClinics(state,p).map(id=>`<span class="clinic-chip">${clinicName(id)}</span>`).join('')||'—'}</td><td><div class="row patient-row-actions">${doctor()?button('Φάκελος','patientSummary',p.id,'secondary')+button('Ιστορικό','record',p.id,'secondary'):''}${button('Ραντεβού','followup',p.id)}${button('Επεξεργασία','editPatient',p.id,'secondary')}</div></td></tr>`;}).join('')}</tbody></table></div>${!rows.length?'<p class="empty">Δεν βρέθηκαν ασθενείς με αυτά τα φίλτρα.</p>':''}<div class="pagination row between"><span>Εμφανίζονται ${all.length?(patientPage-1)*patientPageSize+1:0}–${Math.min(patientPage*patientPageSize,all.length)} από ${all.length}</span><div class="row"><button type="button" data-action="patientPage" data-id="${patientPage-1}" ${patientPage===1?'disabled':''}>‹ Προηγούμενη</button><span>Σελίδα ${patientPage} / ${pages}</span><button type="button" data-action="patientPage" data-id="${patientPage+1}" ${patientPage===pages?'disabled':''}>Επόμενη ›</button></div></div>`;}
function refreshPatientResults(){if($('patientResults'))$('patientResults').innerHTML=patientRows();}
function renderPatientListFilters(){for(const [id,value] of [['patientStatusFilter',patientStatusFilter],['patientClinicFilter',patientClinicFilter],['patientFavFilter',patientFavFilter],['search',patientQuery],['patientLastFrom',patientLastFrom?displayDate(patientLastFrom):''],['patientLastTo',patientLastTo?displayDate(patientLastTo):'']])if($(id))$(id).value=id.startsWith('patientLast')?formatMask(value,'date'):value;}
function patientBanner(p,selector='summaryPatient'){const last=patientLastVisit(state,p.id);const now=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Athens',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());const next=state.appointments.filter(a=>a.patientId===p.id&&a.status==='scheduled'&&(a.date>today()||a.date===today()&&a.time>=now)).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time))[0];const initials=(p.lastName||p.name).slice(0,1)+(p.firstName||'').slice(0,1);return `<section class="card patient-banner">${patientSelect(selector,p.id)}<div class="patient-banner-main"><div class="patient-avatar" aria-hidden="true">${esc(initials)}</div><div><h2>${esc(p.name)}</h2><p>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p><p>${esc(p.phone)||'Χωρίς τηλέφωνο'}${p.email?' · '+esc(p.email):''}</p></div><dl><div><dt>Τελευταία επίσκεψη</dt><dd>${last?displayDate(last.date):'Δεν υπάρχει οριστικοποιημένη'}</dd></div><div><dt>Επόμενο ραντεβού</dt><dd>${next?displayDate(next.date)+' · '+next.time:'Δεν έχει προγραμματιστεί'}</dd></div><div><dt>Κατάσταση</dt><dd><span class="patient-status status-${p.status||'active'}">${PATIENT_STATUSES[p.status||'active']}</span></dd></div></dl></div>${clinicalAlert(p)}<div class="row">${button('Νέα επίσκεψη','newVisit',p.id)}${button('Νέο ραντεβού','followup',p.id,'secondary')}${button('Επεξεργασία στοιχείων','editPatient',p.id,'secondary')}</div></section>`;}
function clinicalPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const tabs=`<div class="patient-tabs" role="group" aria-label="Ενότητες ιατρικού φακέλου">${button('Επισκόπηση','clinicalTab','overview',clinicalTab==='overview'?'active':'secondary')}${button('Ιατρικό ιστορικό / LUTS','clinicalTab','history',clinicalTab==='history'?'active':'secondary')}${button('Επισκέψεις / Χρονολόγιο','record',p.id,'secondary')}${button('Εξετάσεις','openExams',p.id,'secondary')}${button('Απεικόνιση','openImaging',p.id,'secondary')}${button('Σημειώσεις','clinicalTab','notes',clinicalTab==='notes'?'active':'secondary')}${button('Έγγραφα','clinicalTab','documents',clinicalTab==='documents'?'active':'secondary')}</div>`;if(clinicalTab==='documents')return patientBanner(p)+tabs+documentsPanel(p);if(clinicalTab==='history'){const editor=clinicalEditor();return patientBanner(p)+tabs+editor.slice(editor.indexOf('<form id="clinicalForm">'));}if(clinicalTab==='notes')return patientBanner(p)+tabs+`<section class="card"><h2>Σημειώσεις φακέλου</h2><form id="summaryNotesForm"><label>Σημειώσεις του γιατρού<textarea id="summaryNotesText">${esc(p.notes)}</textarea></label><div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση σημειώσεων</button></form></section>`;return patientBanner(p)+tabs+overviewCards(p)+referencePanel('record-reference.png','Ιατρικός φάκελος');}
function detailRows(rows){return `<dl class="detail-rows">${rows.map(([label,value])=>`<div><dt>${label}</dt><dd>${esc(value)||'—'}</dd></div>`).join('')}</dl>`;}
function overviewCards(p){const c=p.clinical||emptyClinical(),visits=state.visits.filter(v=>v.patientId===p.id).sort((a,b)=>b.date.localeCompare(a.date)),exams=(state.examinations||[]).filter(e=>e.patientId===p.id).sort((a,b)=>b.date.localeCompare(a.date)),files=exams.flatMap(e=>e.files.map(f=>({...f,date:e.date})));return `<div class="patient-overview"><section class="card"><h2>Βασικά στοιχεία</h2>${detailRows([['Επίθετο',p.lastName],['Όνομα',p.firstName],['Ηλικία',p.age+' ετών'],['Φύλο',({male:'Άνδρας',female:'Γυναίκα',other:'Άλλο'})[p.sex]||'Δεν έχει καταγραφεί'],['Τηλέφωνο',p.phone],['Email',p.email],['Διεύθυνση',p.address],['Επάγγελμα',p.occupation],['Ασφαλιστικός φορέας',p.insurance],['Συνοδός / επικοινωνία',p.contact]])}</section><section class="card"><h2>Σύντομο ιατρικό ιστορικό</h2><p><strong>Καπνιστική συνήθεια:</strong> ${smokingOptions.find(([key])=>key===c.smoking)?.[1]||'Δεν έχει καταγραφεί'}</p>${[['Διαγνώσεις',c.diagnoses],['Οικογενειακό ιστορικό',c.familyHistory],['Ουρολογικό ιστορικό',c.urologyHistory],['Ανδρολογικό ιστορικό',c.andrologyHistory],['LUTS',c.luts]].map(([label,text])=>`<h3>${label}</h3><p class="prewrap">${esc(text)||'Δεν έχει καταγραφεί.'}</p>`).join('')}${button('Επεξεργασία ιστορικού','clinicalTab','history','secondary')}</section><section class="card"><h2>Τρέχουσα αγωγή</h2><p class="prewrap">${esc(c.medications)||'Δεν έχει καταγραφεί φαρμακευτική αγωγή.'}</p>${button('Ενημέρωση φαρμάκων','clinicalTab','history','secondary')}<h2 class="section-gap">Σημειώσεις</h2><p class="prewrap">${esc(p.notes)||'Δεν υπάρχουν σημειώσεις.'}</p>${button('Επεξεργασία σημειώσεων','clinicalTab','notes','secondary')}</section><section class="card psa-panel"><div class="row between"><h2>PSA · εξέλιξη τιμών</h2>${button('Νέα καταχώριση PSA','newPsa','','secondary')}</div>${psaChart(p.id)}</section><section class="card"><h2>Πρόσφατες επισκέψεις</h2>${visits.slice(0,5).map(v=>`<div class="compact-entry"><span>${displayDate(v.date)} · ${v.status==='draft'?'Προσχέδιο':'Οριστικοποιημένη'}</span><p>${esc(v.reason)||'Χωρίς λόγο επίσκεψης'}</p>${button(v.status==='draft'?'Συνέχεια':'Αναφορά',v.status==='draft'?'editVisit':'report',v.id,'secondary')}</div>`).join('')||'<p>Δεν έχουν καταχωριστεί επισκέψεις.</p>'}${button('Πλήρες ιστορικό','record',p.id,'secondary')}</section><section class="card"><h2>Πρόσφατες εξετάσεις</h2>${exams.slice(0,5).map(e=>`<div class="compact-entry"><span>${displayDate(e.date)} · ${EXAM_TYPES[e.category]}</span><p>${esc(e.title)} · ${esc(e.result)||'Χωρίς αποτέλεσμα'}</p>${button('Προβολή','openExamFromHistory',e.id,'secondary')}</div>`).join('')||'<p>Δεν έχουν καταχωριστεί εξετάσεις.</p>'}${button('Όλες οι εξετάσεις','openExams',p.id,'secondary')}</section><section class="card"><h2>Πρόσφατα έγγραφα</h2>${files.slice(0,6).map(f=>`<div class="compact-entry"><p>${esc(f.name)}</p><span>${displayDate(f.date)}</span> ${button('Λήψη','downloadExam',f.id,'secondary')}</div>`).join('')||'<p>Δεν υπάρχουν αποθηκευμένα αρχεία.</p>'}${button('Έγγραφα / Προσθήκη','openExams',p.id,'secondary')}</section></div>`;}
function psaChart(id){const values=psaValues(state,id);if(!values.length)return '<p>Δεν υπάρχουν αριθμητικές καταχωρίσεις PSA με μονάδα ng/mL. Οι υπόλοιπες εξετάσεις παραμένουν διαθέσιμες στην ενότητα Εξετάσεις.</p>';const start=Date.parse(values[0].date),end=Date.parse(values.at(-1).date),max=Math.max(1,...values.map(v=>v.value))*1.15;const points=values.map(v=>({x:end===start?300:60+480*(Date.parse(v.date)-start)/(end-start),y:210-170*v.value/max,...v}));return `<svg class="psa-chart" viewBox="0 0 600 270" role="img" aria-label="Χρονολογική εξέλιξη των καταχωρισμένων τιμών PSA σε ng/mL"><line x1="60" y1="40" x2="60" y2="210" stroke="currentColor"/><line x1="60" y1="210" x2="550" y2="210" stroke="currentColor"/>${[0,.5,1].map(f=>`<text x="48" y="${214-170*f}" text-anchor="end">${(max*f).toFixed(1)}</text>`).join('')}<polyline fill="none" stroke="#087df0" stroke-width="3" points="${points.map(p=>p.x+','+p.y).join(' ')}"/>${points.map(p=>`<circle cx="${p.x}" cy="${p.y}" r="5" fill="#087df0"><title>${displayDate(p.date)} · ${p.value} ng/mL</title></circle>`).join('')}<text x="60" y="240">${displayDate(values[0].date)}</text><text x="550" y="240" text-anchor="end">${values.length>1?displayDate(values.at(-1).date):''}</text><text x="60" y="28">ng/mL</text></svg><details><summary>Τιμές και ημερομηνίες</summary>${values.map(v=>`<p>${displayDate(v.date)} · ${v.value} ng/mL</p>`).join('')}</details><p class="field-hint">Μόνο αποθηκευμένες τιμές με ρητή μονάδα ng/mL. Δεν γίνεται αυτόματη ιατρική αξιολόγηση ή εφαρμογή γενικού ορίου.</p>`;}

const HISTORY_TYPES={visits:'Επισκέψεις',exams:'Εξετάσεις & έγγραφα',imaging:'Απεικονίσεις',appointments:'Ραντεβού',profile:'Ενημέρωση ιστορικού',notes:'Σημειώσεις'};
function filteredHistory(){return timelineEvents(state,selectedPatient).filter(e=>(!historyType||e.type===historyType)&&(!historyFrom||e.date>=historyFrom)&&(!historyTo||e.date<=historyTo)&&matchesHistoryText(e,recordQuery));}
function matchesHistoryText(event,q){return (event.title+' '+event.text).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('el').includes(q.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('el'));}
function visitHistoryCard(v){return `<article class="card record history-event type-visits"><div class="row between"><h3>${displayDate(v.date)} · ${clinicName(v.clinic)}</h3><span class="pill">${v.status==='draft'?'Προσχέδιο':'Οριστικοποιημένη'}</span></div><p><strong>${esc(v.reason)||'Κενό προσχέδιο'}</strong></p><p class="prewrap">${esc(v.plan)}</p><small>Καταχώριση: ${esc(v.author)} · ${v.revisions.length} διορθώσεις</small><div class="row actions">${button(v.status==='draft'?'Συνέχεια προσχεδίου':'Διόρθωση με ιστορικό','editVisit',v.id)}${button('PRINT / E-MAIL · Αναφορά','report',v.id,'secondary')}</div>${v.revisions.length?`<details><summary>Προηγούμενες εκδόσεις</summary>${v.revisions.map(r=>`<div class="card"><strong>${esc(r.reason)}</strong><p>${displayDate(r.snapshot.date||v.date)} · ${clinicName(r.snapshot.clinic||v.clinic)}</p>${[['reason','Λόγος'],['history','Ιστορικό'],['exam','Κλινική εξέταση'],['assessment','Γνωμάτευση / παρατηρήσεις'],['plan','Πλάνο']].map(([key,label])=>`<p class="prewrap"><strong>${label}:</strong> ${esc(r.snapshot[key])||'—'}</p>`).join('')}<small>${esc(r.author)} · ${esc(r.at)}</small></div>`).join('')}</details>`:''}</article>`;}
function historyEventCard(e){if(e.type==='visits')return visitHistoryCard(state.visits.find(v=>v.id===e.sourceId));return `<article class="card history-event type-${e.type}"><div class="row between"><strong>${displayDate(e.date)}</strong><span class="pill">${HISTORY_TYPES[e.type]}</span></div><h3>${esc(e.title)}</h3><p class="prewrap">${esc(e.text.slice(0,280))}${e.text.length>280?'…':''}</p>${e.text.length>280?`<details><summary>Πλήρης καταχώριση</summary><p class="prewrap">${esc(e.text)}</p></details>`:''}<div class="row">${e.type==='imaging'?button('Προβολή απεικόνισης','openImaging',e.sourceId,'secondary'):e.type==='exams'?button('Προβολή εξέτασης','openExamFromHistory',e.sourceId,'secondary'):e.type==='appointments'?button('Προβολή στο ημερολόγιο','openAppointmentHistory',e.sourceId,'secondary'):button('Ιατρικός φάκελος','patientSummary',selectedPatient,'secondary')}</div></article>`;}
function recordPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const all=timelineEvents(state,p.id),events=filteredHistory(),counts=Object.fromEntries(Object.keys(HISTORY_TYPES).map(type=>[type,all.filter(e=>e.type===type).length]));return patientBanner(p,'recordPatient')+`<section class="card history-patient-lookup">${field('Εύρεση ασθενή · 2–3 πρώτα γράμματα επιθέτου ή Α.Μ.Κ.Α.','historyPatientSearch','','text','autocomplete="off" aria-controls="historyPatientResults"')}<div id="historyPatientResults" aria-live="polite"></div></section><div class="history-layout"><aside class="card history-filters"><h2>Φίλτρα ιστορικού</h2>${button('Όλα τα γεγονότα · '+all.length,'historyKind','','secondary')}${Object.entries(HISTORY_TYPES).map(([id,label])=>button(label+' · '+counts[id],'historyKind',id,historyType===id?'active':'secondary')).join('')}<p class="field-hint">Εμφανίζονται μόνο γεγονότα που υπάρχουν στον συγκεκριμένο φάκελο.</p>${button('Καθαρισμός φίλτρων','historyReset','','secondary')}</aside><section><div class="card"><div class="row between"><h2>Χρονολογική προβολή · ${events.length}</h2>${button(historyLayout==='timeline'?'Προβολή λίστας':'Προβολή χρονολογίου','historyLayout','','secondary')}${button('PRINT / PDF · Ιστορικό','historyPrint','','secondary')}</div><form id="recordSearchForm"><div class="history-filter-controls">${field('Αναζήτηση κειμένου στο ιστορικό','recordSearch',recordQuery)}${field('Από · ΗΗ/ΜΜ/ΕΕΕΕ','historyFrom',historyFrom?displayDate(historyFrom):'','text','inputmode="numeric"')}${field('Έως · ΗΗ/ΜΜ/ΕΕΕΕ','historyTo',historyTo?displayDate(historyTo):'','text','inputmode="numeric"')}</div><div id="formError" role="alert"></div><div class="row"><button type="submit">Εφαρμογή φίλτρων</button>${button('Καθαρισμός αναζήτησης','clearRecordSearch','','secondary')}</div></form></div><div class="history-events ${historyLayout}">${events.map(historyEventCard).join('')||'<p class="card empty">Δεν βρέθηκαν γεγονότα με αυτά τα φίλτρα.</p>'}</div></section><aside><section class="card"><h2>Σύνοψη φακέλου</h2>${detailRows(Object.entries(HISTORY_TYPES).map(([type,label])=>[label,counts[type]]))}</section><section class="card"><h2>Καταγεγραμμένες διαγνώσεις</h2><p class="prewrap">${esc(p.clinical?.diagnoses)||'Δεν έχουν καταγραφεί.'}</p><h2>Φαρμακευτική αγωγή</h2><p class="prewrap">${esc(p.clinical?.medications)||'Δεν έχει καταγραφεί.'}</p>${button('Ενημέρωση ιατρικού ιστορικού','openClinical',p.id,'secondary')}</section></aside></div>${optionsActions()}${referencePanel('history-reference.png','Χρονολογικό ιστορικό')}`;}
function historyReportPage(){const p=patient(selectedPatient);if(!p)return '<p>Επιλέξτε ασθενή από το ιστορικό.</p>';const events=filteredHistory();return `<div class="actions row">${button('PRINT · Εκτύπωση / αποθήκευση PDF','print')}${button('Επιστροφή στο ιστορικό','record',p.id,'secondary')}</div><article class="report" id="historyReportDocument"><h2>UroMed Nexus Suite</h2><h3>Δοκιμαστικό ιστορικό ασθενή</h3><p><strong>${esc(p.name)}</strong><br>Α.Μ.Κ.Α.: ${esc(p.amka)||'—'} · ${p.age} ετών</p><div class="notice">Μόνο φανταστικά δεδομένα · ${events.length} γεγονότα με τα επιλεγμένα φίλτρα.</div>${events.map(e=>`<section><h3>${displayDate(e.date)} · ${HISTORY_TYPES[e.type]}</h3><p><strong>${esc(e.title)}</strong></p><p>${esc(e.text)}</p></section>`).join('')||'<p>Δεν υπάρχουν γεγονότα με αυτά τα φίλτρα.</p>'}<footer>${version} · Εκπαιδευτική αναφορά, όχι πραγματικός ιατρικός φάκελος.</footer></article>`;}

function documentsPanel(p){const files=(state.examinations||[]).filter(e=>e.patientId===p.id).sort((a,b)=>b.date.localeCompare(a.date)).flatMap(e=>e.files.map(f=>({...f,date:e.date,title:e.title})));return `<section class="card"><h2>Έγγραφα και αρχεία εξετάσεων · ${files.length}</h2>${files.map(f=>`<article class="compact-entry"><p><strong>${esc(f.name)}</strong></p><p>${displayDate(f.date)} · ${esc(f.title)} · ${(f.size/1024).toFixed(1)} KB</p>${button('Λήψη αρχείου','downloadExam',f.id,'secondary')}</article>`).join('')||'<p>Δεν υπάρχουν αποθηκευμένα αρχεία στον φάκελο.</p>'}${button('Προσθήκη μέσω εξέτασης','openExams',p.id)}</section>`;}

let aiReference='ct';
function navIcon(id){const paths={home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',patients:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-4',calendar:'M3 5h18v16H3zM7 2v6M17 2v6M3 11h18M7 15h2M15 15h2',workspaces:'M4 21V5h16v16M9 21v-5h6v5M8 9h2M14 9h2M8 12h2M14 12h2',clinical:'M3 6h7l2 3h9v12H3z',examinations:'M9 2h6M10 2v7L3 21h18L14 9V2M7 15h10',imaging:'M3 3h18v18H3zM3 17l6-6 4 4 3-3 5 5M16 7h1',prescription:'M5 21V3h6a5 5 0 0 1 0 10H5M11 13l10 8M21 13l-9 8',reports:'M4 21V10h3v11M11 21V3h3v18M18 21v-7h3v7',record:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18M12 7v6l4 2',visit:'M5 3h14v18H5zM8 8h8M12 5v6M8 15h8',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4M12 18h.01M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};return `<svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.reports}"/></svg>`;}
function dashboardPage(){const appointments=state.appointments.filter(a=>a.date===today()),scheduled=appointments.filter(a=>a.status==='scheduled').sort((a,b)=>a.time.localeCompare(b.time)),final=state.visits.filter(v=>v.date===today()&&v.status==='final'),drafts=state.visits.filter(v=>v.status==='draft');return `<section class="dashboard-welcome"><h2>Καλώς ήρθατε, ${esc(account.label)}</h2><p>UroMed Nexus Suite · Το δοκιμαστικό ιατρείο σας</p></section><div class="clinic-tiles">${clinics().map((c,i)=>`<article class="clinic-tile tile-${i}">${navIcon('workspaces')}<h2>${esc(c.name)}</h2><p>Σημερινά ραντεβού: ${appointments.filter(a=>a.clinic===c.id&&a.status==='scheduled').length}</p>${button('Άνοιγμα προγράμματος →','clinic',c.id,'secondary')}</article>`).join('')}</div><div class="dashboard-panels"><section class="card"><h2>Σημερινό πρόγραμμα</h2>${scheduled.map(a=>`<div class="dashboard-appointment"><strong>${a.time}</strong><span>${esc(patient(a.patientId)?.name)}<small>${clinicName(a.clinic)} · ${a.duration} λεπτά</small></span>${doctor()?button('Φάκελος','patientSummary',a.patientId,'secondary'):button('Ραντεβού','openAppointmentHistory',a.id,'secondary')}</div>`).join('')||'<p class="empty">Δεν υπάρχουν προγραμματισμένα ραντεβού σήμερα.</p>'}${button('Όλο το ημερολόγιο','nav','calendar','secondary')}</section><section class="card"><h2>Γρήγορες ενέργειες</h2><div class="quick-action-grid">${button('Νέος ασθενής','newPatient')}${button('Νέο ραντεβού','newAppointment')}${doctor()?button('Καταχώριση επίσκεψης','newVisit')+button('Συνταγογράφηση · ΗΔΙΚΑ','nav','prescription')+button('Εξετάσεις','nav','examinations')+button('Αναφορές / PDF','nav','reports'):''}</div></section><section class="card"><h2>Σύνοψη ημέρας</h2>${detailRows([['Προγραμματισμένα ραντεβού',scheduled.length],['Πραγματοποιημένα ραντεβού',appointments.filter(a=>a.status==='completed').length],['Ακυρωμένα',appointments.filter(a=>a.status==='cancelled').length],...(doctor()?[['Οριστικές επισκέψεις',final.length],['Προσχέδια επισκέψεων · όλα',drafts.length]]:[])])}</section><section class="card"><h2>Γρήγορη πρόσβαση ασθενών</h2>${[...state.patients].sort((a,b)=>(patientLastVisit(state,b.id)?.date||'').localeCompare(patientLastVisit(state,a.id)?.date||'')).slice(0,5).map(p=>`<div class="dashboard-appointment"><span>${esc(p.name)}<small>${patientLastVisit(state,p.id)?displayDate(patientLastVisit(state,p.id).date):'Χωρίς οριστική επίσκεψη'}</small></span>${button(doctor()?'Φάκελος':'Στοιχεία',doctor()?'patientSummary':'editPatient',p.id,'secondary')}</div>`).join('')||'<p>Προσθέστε φανταστικό ασθενή.</p>'}</section></div>${referencePanel('dashboard-reference.png','Αρχικό σχέδιο πίνακα ελέγχου')}`;}
function workspacesPage(){return `<div class="grid">${clinics().map(c=>`<section class="card"><h2>${esc(c.name)}</h2><p>Προγραμματισμένα ραντεβού: ${state.appointments.filter(a=>a.clinic===c.id&&a.status==='scheduled').length}</p>${button('Άνοιγμα ημερολογίου','clinic',c.id)}</section>`).join('')}</div><section class="card"><h2>Οργάνωση χώρων</h2><p>Χρόνος μετακίνησης μεταξύ διαφορετικών ιατρείων: ${state.settings.travelMinutes||0} λεπτά. Συνυπολογίζεται στον έλεγχο επικαλύψεων.</p><p>Οι ονομασίες και η ενεργοποίηση του Νοσοκομείου ρυθμίζονται από τον ADMIN. Η ρύθμιση ωραρίων προσωπικού δεν έχει υλοποιηθεί.</p></section>`;}
function prescriptionPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const copies=(state.examinations||[]).filter(e=>e.patientId===p.id&&e.category==='prescription').sort((a,b)=>b.date.localeCompare(a.date));return patientBanner(p)+`<div class="prescription-layout"><section class="card idika-access"><div class="eyebrow">ΕΠΙΣΗΜΗ ΥΠΗΡΕΣΙΑ · ΕΞΩΤΕΡΙΚΗ ΠΡΟΣΒΑΣΗ</div><h2>Ηλεκτρονική συνταγογράφηση μέσω ΗΔΙΚΑ</h2><p>Η επίσημη συνταγογράφηση πραγματοποιείται αποκλειστικά στην υπηρεσία της ΗΔΙΚΑ.</p><a class="idika-button" href="https://www.e-prescription.gr/" target="_blank" rel="noopener noreferrer" referrerpolicy="no-referrer">↗ Άνοιγμα στην ΗΔΙΚΑ</a><p>Συνδέεστε εσείς με τους προσωπικούς σας κωδικούς στην αυθεντική υπηρεσία. Το UroMed δεν τους ζητά ούτε τους αποθηκεύει.</p><p class="notice">Δεν υπάρχει ενσωμάτωση ή αυτόματη μεταφορά προσωπικών ή ιατρικών δεδομένων προς ή από την ΗΔΙΚΑ.</p></section><section class="card"><h2>Εσωτερική καταγραφή αγωγής</h2><form id="prescriptionForm"><label>Φάρμακα / οδηγίες του γιατρού<textarea id="prescriptionMedications">${esc(p.clinical?.medications)}</textarea></label><p class="field-hint">Καταγραφή για παρακολούθηση. Δεν αποτελεί επίσημη συνταγή, έλεγχο δοσολογίας ή αλληλεπιδράσεων.</p><div id="formError" role="alert"></div><button type="submit">SAVE · Αποθήκευση αγωγής</button></form></section><section class="card"><h2>Αντίγραφα συνταγών · χειροκίνητη εισαγωγή</h2>${button('Προσθήκη αντιγράφου','prescriptionCopy')}${copies.map(e=>`<article><h3>${displayDate(e.date)} · ${esc(e.title)}</h3><p class="prewrap">${esc(e.notes)}</p>${e.files.map(f=>`<p>${esc(f.name)} ${button('Λήψη αντιγράφου','downloadExam',f.id,'secondary')}</p>`).join('')||'<p>Δεν έχει επισυναφθεί αρχείο.</p>'}</article>`).join('')||'<p>Δεν έχουν εισαχθεί αντίγραφα στον συγκεκριμένο φάκελο.</p>'}</section><section class="card"><h2>Βοηθός ΤΝ · μελλοντική δυνατότητα</h2><p>Δεν παρέχονται αυτόματες προτάσεις φαρμάκων ή έκδοση συνταγής. Η καταγραφή και η αξιολόγηση γίνονται από τον γιατρό.</p></section></div>${referencePanel('prescription-reference-1.png','Αρχική σχεδιαστική πρόταση συνταγογράφησης')}${referencePanel('prescription-reference-2.png','Εναλλακτική σχεδιαστική πρόταση συνταγογράφησης')}`;}
function reportsPage(){if(!patient(selectedPatient))selectedPatient=state.patients[0]?.id;const p=patient(selectedPatient);if(!p)return '<p>Προσθέστε πρώτα φανταστικό ασθενή.</p>';const visits=state.visits.filter(v=>v.patientId===p.id&&v.status==='final').sort((a,b)=>b.date.localeCompare(a.date));return patientBanner(p)+`<section class="card"><h2>Οριστικές επισκέψεις · Αναφορές</h2><p>Επιλέξτε αναφορά για προεπισκόπηση, εκτύπωση ή αποθήκευση ως PDF από τον browser.</p>${visits.map(v=>`<article class="dashboard-appointment"><span>${displayDate(v.date)} · ${esc(v.reason)}<small>${clinicName(v.clinic)}</small></span>${button('Αναφορά / PDF','report',v.id,'secondary')}</article>`).join('')||'<p>Δεν υπάρχουν οριστικές επισκέψεις για αυτόν τον ασθενή.</p>'}<div class="row">${button('Χρονολόγιο / εκτύπωση ιστορικού','record',p.id,'secondary')}${enabled('programPrint')?button('PRINT · Πρόγραμμα','program','','secondary'):''}</div></section>`;}
